import{z as l,x as s,o as r,c as p,q as n,j as o,D as E,d as t,s as B,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"影子银行","description":"","frontmatter":{"title":"影子银行","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shadow-banking.md","filePath":"econ/shadow-banking.md","lastUpdated":1791413859000}'),d={name:"econ/shadow-banking.md"};function c(h,a,u,C,F,D){const i=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="影子银行" tabindex="-1">影子银行 <a class="header-anchor" href="#影子银行" aria-label="Permalink to &quot;影子银行&quot;">​</a></h1><div class="epigraph"><p>期限转换若被资本与流动性比率赶上，就会改写负债合同，搬到并表银行外面继续做。</p><footer>—— 据 Pozsar, Adrian, Ashcraft and Boesky, Shadow Banking, FRBNY Staff Report / Economic Policy Review；Gorton and Metrick, Securitized Banking and the Run on Repo, Journal of Financial Economics 2012 整理</footer></div><p>定位：<a href="/econ/lcr-nsfr">上一课</a>。并表银行已经被两道流动性比率加上资本阀钉住。本课缺口是跑到监管外面的期限转换：资产支持商业票据、回购、货币市场基金把短而可提取的债权，配到长而难变现的信贷。不重写 LCR 公式，不把影子银行写成另一套 Diamond–Dybvig 证明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gurley–Shaw 的转换功能不要求牌照。若银行持有贷款的稳定资金变贵，贷款可以先被证券化，再由愿意持有短负债的实体去融资：ABCP 管道、经销商的回购账、MMF 的可赎回份额。公众仍以为自己持有「近货币」，发行人不受存款保险、LCR 与巴塞尔分子约束。Pozsar 等人把这条链称为影子银行：从贷款到可赎回批发债权的切割与再包装。</p><p>缺口不是道德故事，而是：同一期限转换换了合同之后，挤兑以批发形式出现——赎回、加 haircut、停滚发行。Gorton 与 Metrick 把回购 haircut 的跳升写成这种挤兑的价格。</p><p><span class="marginnote">影子不是「非银行所以不创造信用」。它创造的是可交易的近货币债权。近货币一旦按面值被当成结算替代，挤兑的逻辑与活期存款同构，法律身份不同。</span></p><p><span class="marginnote">常见误区：初学者容易以为影子银行是「不创造信用的中介」或「非法金融」。实际上它做的正是银行那套期限转换，只是合同换成了 ABCP、回购、MMF 份额这些「近货币」债权——功能同构，牌照与监管身份不同。</span></p><p><span class="marginnote">数字实例：一条管道持有 1 亿元 5 年期资产支持证券，靠 1 个月期 ABCP 滚动融资。买家一旦停滚，1 亿元缺口当天出现，只能卖券或动用银行便利——5 年资产对 1 个月负债的错配，就是挤兑的火药。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿一条简化的链。贷款从银行或非银行发起，进资产支持证券；优先级再被管道用 ABCP 融资，或被经销商用回购融资；MMF 持有 ABCP / 回购，对家庭与公司发行可赎回份额。每一环都在做期限或流动性转换，每一环的「存款保险」往往是超额抵押、第三方流动性便利或发行人的隐担保，而不是基金。</p><p>挤兑的操作：MMF 赎回迫使管道停滚 ABCP；管道卖券或抽流动性便利；经销商提高回购 haircut，等于要求更多抵押来滚动同一负债——Gorton–Metrick 的「run on repo」。haircut 上升是数量配给，不是温和的价格调整：同一资产池能支撑的批发负债突然变少。</p>',12)),(r(),o(A,null,{default:E(()=>[B(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAN%5B%22%E8%B4%B7%E6%AC%BE%20%2F%20%E8%AF%81%E5%88%B8%E5%8C%96%22%5D%20--%3E%20ABCP%5B%22ABCP%20%E7%AE%A1%E9%81%93%22%5D%0A%20%20LOAN%20--%3E%20REPO%5B%22%E7%BB%8F%E9%94%80%E5%95%86%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20ABCP%20--%3E%20MMF%5B%22%E8%B4%A7%E5%B8%81%E5%B8%82%E5%9C%BA%E5%9F%BA%E9%87%91%22%5D%0A%20%20REPO%20--%3E%20MMF%0A%20%20MMF%20--%3E%20RED%5B%22%E4%BB%BD%E9%A2%9D%E8%B5%8E%E5%9B%9E%22%5D%0A%20%20REPO%20--%3E%20HC%5B%22haircut%20%E8%B7%B3%E5%8D%87%22%5D%0A%20%20RED%20--%3E%20FIRE%5B%22%E5%BC%BA%E5%88%B6%E5%87%BA%E5%94%AE%22%5D%0A%20%20HC%20--%3E%20FIRE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与并表银行的关系：银行常常提供流动性便利或把管道留在监管资本的缝里。影子链不是与银行平行的另一个星球，是被比率赶出去的表外腿。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是监管相对价格。资本与 LCR/NSFR 提高并表期限转换的成本，不提高未并表近货币的成本，于是转换迁出。迁出之后，挤兑没有存款保险删坏均衡，也没有明确的 Bagehot 抵押窗口——除非危机中把窗口扩到经销商与 MMF。于是上一课的流动性比率在并表内生效，在系统层面被绕开。",-1)),(r(),o(A,null,{default:E(()=>[B(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E8%B5%84%E6%9C%AC%E4%B8%8E%20LCR%2FNSFR%20%E6%AF%94%E7%8E%87%22%5D%20--%3E%20COSTB%5B%22%E5%B9%B6%E8%A1%A8%E6%9C%9F%E9%99%90%E8%BD%AC%E6%8D%A2%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20COSTB%20--%3E%20MIG%5B%22%E8%BD%AC%E6%8D%A2%E8%BF%81%E5%88%B0%E8%A1%A8%E5%A4%96%E8%BF%91%E8%B4%A7%E5%B8%81%E5%90%88%E5%90%8C%22%5D%0A%20%20MIG%20--%3E%20NOSAFE%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E6%97%A0%E5%AD%98%E6%AC%BE%E4%BF%9D%E9%99%A9%E3%80%81%E4%B8%8D%E5%8F%97%E6%AF%94%E7%8E%87%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20NOSAFE%20--%3E%20RUN%5B%22%E6%89%B9%E5%8F%91%E6%8C%A4%E5%85%91%3A%20%E8%B5%8E%E5%9B%9E%E4%B8%8E%20haircut%20%E8%B7%B3%E5%8D%87%22%5D%0A%20%20RUN%20--%3E%20BYPASS%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E6%AF%94%E7%8E%87%E5%9C%A8%E7%B3%BB%E7%BB%9F%E5%B1%82%E9%9D%A2%E8%A2%AB%E7%BB%95%E5%BC%80%22%5D%0A%20%20GUAR%5B%22%E9%9A%90%E6%8B%85%E4%BF%9D%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%BF%E5%88%A9%22%5D%20--%3E%20BACK%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E9%A3%8E%E9%99%A9%E5%9B%9E%E6%B5%81%E5%B9%B6%E8%A1%A8%E9%93%B6%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>这与<a href="/econ/bank-contagion">传染</a>的网络同构：管道、经销商、MMF 互相持有短债权，不完全连接时 haircut 与赎回沿链传递。差别是合同：活期存款有序贯服务与面值；回购有抵押和 haircut，挤兑表现为抵押率而不是柜台上的排队。</p><h3 id="haircut-是批发版的提款" tabindex="-1">haircut 是批发版的提款 <a class="header-anchor" href="#haircut-是批发版的提款" aria-label="Permalink to &quot;haircut 是批发版的提款&quot;">​</a></h3><p>haircut 从 0 到正，等于债权人提取一部分融资、留下同一券。资产没有必要先「变坏」到资不抵债；抵押率的信念可以自实现，把流动性问题做成清偿问题——又是 Bagehot 要分开的那两层，只是发生在银行牌照外。不要把 haircut 跳升读成普通的风险溢价变动；数量上它抽掉的是滚动负债。</p><p><span class="marginnote">术语翻译：「haircut」（折扣）就是回购里抵押品打的折——想借 95 元，得交市值 100、按 95 元估值（haircut 5%）的券当抵押。haircut 从 0% 跳到 5%，同一堆券立刻少融 5% 的钱；跳到 20%，相当于债权人一次性「提走」五分之一的滚动额度，这是数量收缩而不是温和涨价。</span></p><p><span class="marginnote">MMF 的稳定净值承诺，把份额写成准存款。一旦跌破，赎回加速。改革后的浮动净值改变的是合同，不是期限转换本身是否还存在。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把所有非银行中介都叫影子银行：养老金与共同基金持有长期资产、发行不可随时按面值赎回的债权，转换弱。也不要把证券化本身当成挤兑：证券化可以是风险转移；挤兑来自用短负债去持有那些券。本课不写 LOB 上的回购特殊券微观结构——那是量化栏的协议。</p><p>银行课序在此结束。下一课进入公司金融的无摩擦基准 <a href="/econ/modigliani-miller">MM</a>，不再把表外管道当资本结构理论。</p><p>后课默认：期限转换可在监管外用近货币合同继续做；批发挤兑表现为赎回与 haircut，而不是柜面排队。资本与流动性比率赶的是并表银行，不是转换功能。</p><p>隐担保（银行对管道的便利、对 MMF 的声誉）把影子链接回并表。赶出去的往往是资本，不是风险。</p><p>不要用 1983 年的定理直接给 MMF 定价。同构是功能，不是同一篇文章。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本与 LCR/NSFR 改变并表转换的相对成本，转换迁到近货币链。</li><li>Pozsar 的链：贷款 → 证券化 → ABCP / 回购 → MMF。</li><li>Gorton–Metrick：回购 haircut 跳升是批发挤兑。</li><li>出处：Pozsar et al., FRBNY；Gorton and Metrick, <em>JFE</em> 2012。</li></ul>',13))])}const P=l(d,[["render",c]]);export{M as __pageData,P as default};
